effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  vec3 g = mix(c, vec3(gmLum(c)), desat);
  g = mix(g, tint.rgb, fade);
  g = g * (1.0 - rolloff * smoothstep(0.6, 1.0, gmLum(g)));
  vec3 col = mix(c, g, mixAmt);
  gl_FragColor = vec4(col * a, a);
}
